INSERT OR REPLACE INTO "products" ("id","name","type","status","external_references","created_at","updated_at","description","slug","brand","categories","tags","options","default_variant_id","fulfillment_type","tax_category","primary_image","media","seo","rating","related_products","extensions") VALUES('prod_beauteas_white_glossy_mug','BeauTeas White Glossy Tea Mug','Mugs','archived','{"shopify_id":"6905811566759"}','2021-07-14T09:31:10-06:00','2026-06-29T23:10:36.938Z','{"en":"Whether you''re drinking your tea in the morning, at work, or in bed – this mug''s for you! It''s sturdy and glossy and safe in the microwave and dishwasher.\n\n• Ceramic Tea Mug\n• 11 oz mug dimensions: 3.85″ tall, 3.35″ in diameter\n• 15 oz mug dimensions: 4.7″ tall, 3.35″ in diameter\n• Dishwasher and microwave safe\n• Lead and BPA Free"}','beauteas-white-glossy-mug','BeauTeas.com','["cat_drinkware"]',NULL,'[{"id":"size","name":"Size","type":"select","values":[{"id":"11oz","value":"11oz"},{"id":"15oz","value":"15oz"}]}]','variant_beauteas_white_glossy_mug_97549621320','physical','food','{"url":"products/beauteas-white-glossy-mug.jpg","alt_text":"BeauTeas White Glossy Tea Mug"}','[{"url":"products/beauteas-white-glossy-mug.jpg","alt_text":"BeauTeas White Glossy Tea Mug"},{"url":"products/beauteas-white-glossy-mug-2.jpg","alt_text":"BeauTeas White Glossy Tea Mug"},{"url":"products/beauteas-white-glossy-mug-3.jpg","alt_text":"BeauTeas White Glossy Tea Mug"},{"url":"products/beauteas-white-glossy-mug-4.jpg","alt_text":"BeauTeas White Glossy Tea Mug"},{"url":"products/beauteas-white-glossy-mug-5.jpg","alt_text":"BeauTeas White Glossy Tea Mug"},{"url":"products/beauteas-white-glossy-mug-6.jpg","alt_text":"BeauTeas White Glossy Tea Mug"},{"url":"products/beauteas-white-glossy-mug-7.jpg","alt_text":"BeauTeas White Glossy Tea Mug"}]',NULL,NULL,NULL,'{"vendor":"BeauTeas.com","product_type":"Mugs"}');
INSERT OR REPLACE INTO "products" ("id","name","type","status","external_references","created_at","updated_at","description","slug","brand","categories","tags","options","default_variant_id","fulfillment_type","tax_category","primary_image","media","seo","rating","related_products","extensions") VALUES('prod_clearly_calendula_afternoon','Clearly Calendula Afternoon','Tea Bags','active','{"shopify_id":"6648001003687"}','2021-04-17T12:30:33-06:00','2026-07-01 20:08:22','{"en":"Power through your afternoon with our refreshing organic green tea blend crafted for a healthy-glow ritual and sustained energy. This unique blend combines premium Dragonwell and Sencha green teas with lemon verbena, spearmint, peppermint, and calendula petals. Perfect hot or iced, at work, school, or the gym. Calendula, spearmint, and lemon verbena are botanicals long cherished in skincare, and green tea is naturally rich in antioxidants. Enjoy smooth, long-lasting energy while supporting clear, healthy-looking skin. 100% USDA Certified Organic."}','clearly-calendula-afternoon','BeauTeas.com','["cat_frontpage","cat_clearly_calendula"]',NULL,'[{"id":"size","name":"Size","type":"select","values":[{"id":"one-box-10-tea-bags","value":"One box (10 tea bags)"},{"id":"three-boxes-30-tea-bags","value":"Three boxes (30 tea bags)"}]}]','variant_clearly_calendula_afternoon_btcca1','physical','food','{"url":"products/clearly-calendula-afternoon.jpg","alt_text":"Clearly Calendula Afternoon"}','[{"url":"products/clearly-calendula-afternoon.jpg","alt_text":"Clearly Calendula Afternoon"},{"url":"products/clearly-calendula-afternoon-2.jpg","alt_text":"Clearly Calendula Afternoon"},{"url":"products/clearly-calendula-afternoon-3.jpg","alt_text":"Clearly Calendula Afternoon"},{"url":"products/clearly-calendula-afternoon-4.jpg","alt_text":"Clearly Calendula Afternoon"},{"url":"products/clearly-calendula-afternoon-5.jpg","alt_text":"Clearly Calendula Afternoon"},{"url":"products/clearly-calendula-afternoon-6.jpg","alt_text":"Clearly Calendula Afternoon"},{"url":"products/clearly-calendula-afternoon-7.jpg","alt_text":"Clearly Calendula Afternoon"}]',NULL,NULL,NULL,'{"vendor":"BeauTeas.com","product_type":"Tea Bags","ingredients":"Organic Dragonwell Green Tea, Organic Sencha Green Tea, organic lemon verbena, organic spearmint, organic peppermint, organic calendula petals","caffeine":"caffeinated","servings":"10 tea bags per box","benefits":["With botanicals traditionally used in skincare","Supports clear, healthy-looking skin","A refreshing part of your wellness routine","Part of a balanced daily routine","Smooth long-lasting energy","Rich in antioxidants"],"certifications":["USDA Organic"],"brewing":{"temp":"175°F","time":"2-3 minutes"}}');
INSERT OR REPLACE INTO "products" ("id","name","type","status","external_references","created_at","updated_at","description","slug","brand","categories","tags","options","default_variant_id","fulfillment_type","tax_category","primary_image","media","seo","rating","related_products","extensions") VALUES('prod_clearly_calendula_evening','Clearly Calendula Evening','Tea Bags','active','{"shopify_id":"6648004804775"}','2021-04-17T12:32:25-06:00','2026-07-01 20:08:23','{"en":"Wind down your day with our soothing caffeine-free herbal blend crafted for evening relaxation and your overnight skincare ritual. This calming tea combines organic chamomile, rooibos, spearmint, peppermint, and calendula petals. Chamomile and calendula are botanicals traditionally cherished for a calming routine, while rooibos is naturally rich in antioxidants. Enjoy before bed to unwind as part of your evening self-care. 100% USDA Certified Organic and completely caffeine-free."}','clearly-calendula-evening','BeauTeas.com','["cat_frontpage","cat_clearly_calendula"]',NULL,'[{"id":"size","name":"Size","type":"select","values":[{"id":"one-box-10-tea-bags","value":"One box (10 tea bags)"},{"id":"three-boxes-30-tea-bags","value":"Three boxes (30 tea bags)"}]}]','variant_clearly_calendula_evening_btcce1','physical','food','{"url":"products/clearly-calendula-evening.jpg","alt_text":"Clearly Calendula Evening"}','[{"url":"products/clearly-calendula-evening.jpg","alt_text":"Clearly Calendula Evening"},{"url":"products/clearly-calendula-evening-2.jpg","alt_text":"Clearly Calendula Evening"},{"url":"products/clearly-calendula-evening-3.jpg","alt_text":"Clearly Calendula Evening"},{"url":"products/clearly-calendula-evening-4.jpg","alt_text":"Clearly Calendula Evening"},{"url":"products/clearly-calendula-evening-5.jpg","alt_text":"Clearly Calendula Evening"},{"url":"products/clearly-calendula-evening-6.jpg","alt_text":"Clearly Calendula Evening"},{"url":"products/clearly-calendula-evening-7.jpg","alt_text":"Clearly Calendula Evening"}]',NULL,NULL,NULL,'{"vendor":"BeauTeas.com","product_type":"Tea Bags","ingredients":"Organic chamomile, organic rooibos, organic spearmint, organic peppermint, organic calendula petals","caffeine":"caffeine-free","servings":"10 tea bags per box","benefits":["With botanicals traditionally used in skincare","Supports clear, healthy-looking skin","Made with rooibos, prized in skincare","Supports your overnight skincare routine","Soothing and calming","Rich in antioxidants"],"certifications":["USDA Organic"],"brewing":{"temp":"212°F","time":"5-7 minutes"}}');
INSERT OR REPLACE INTO "products" ("id","name","type","status","external_references","created_at","updated_at","description","slug","brand","categories","tags","options","default_variant_id","fulfillment_type","tax_category","primary_image","media","seo","rating","related_products","extensions") VALUES('prod_clearly_calendula_full_package','Clearly Calendula Mega Month','Tea Bags','active','{"shopify_id":"6652115910823"}','2021-04-19T16:23:14-06:00','2026-07-01 20:08:24','{"en":"Live the complete Clearly Calendula ritual with our Mega Month - 9 boxes in all, three boxes each of Morning (black tea), Afternoon (green tea), and Evening (herbal tea). Every box holds 10 compostable tea bags, so you get 90 servings total: a full month of the Morning / Afternoon / Evening routine, one cup of each per day. Energize in the morning, maintain focus in the afternoon, and relax in the evening while supporting your beauty-from-within routine around the clock. All teas are 100% USDA Certified Organic with compostable tea bags made from sugarcane. Our best value for committing to beauty from within, or a generous gift for tea and skincare enthusiasts."}','clearly-calendula-full-package','BeauTeas.com','["cat_clearly_calendula"]',NULL,'[{"id":"title","name":"Title","type":"select","values":[{"id":"default-title","value":"Default Title"}]}]','variant_clearly_calendula_full_package_btccfp','physical','food','{"url":"products/clearly-calendula-full-package.jpg","alt_text":"Clearly Calendula Mega Month"}','[{"url":"products/clearly-calendula-full-package.jpg","alt_text":"Clearly Calendula Mega Month"},{"url":"products/clearly-calendula-full-package-2.jpg","alt_text":"Clearly Calendula Mega Month"},{"url":"products/clearly-calendula-full-package-3.jpg","alt_text":"Clearly Calendula Mega Month"},{"url":"products/clearly-calendula-full-package-4.jpg","alt_text":"Clearly Calendula Mega Month"}]',NULL,NULL,NULL,'{"vendor":"BeauTeas.com","product_type":"Tea Bags","contents":"9 boxes · 90 tea 