INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(4,'About Us','about-us',replace('<div style="display: none;"></div>\n<div style="display: none;"></div>\n<div style="display: none;"></div>\n<p>BeauTeas was created by blending a love of the beauty community with a love for nourishing the body (and soul) with all-natural organic plant-based goodness.  We believe that the best way to improve how your body looks and feels is through clean plant-based nutrition.  By blending organic flowers and powerful, healing herbs to make tasty hydrating teas, our products make it easy for anyone to improve their skin and appearance without slathering on harsh chemicals.</p>\n<p>Our motto is Build Your Beauty From Within.  Trust us, we still love makeup, moisturizers, serums, and sunscreens!  But regularly drinking our teas will give you healthy long term improvements that you''ll appreciate every time you look in the mirror.</p>\n<p>Our founder, Dana, has been passionate about beauty and the beauty community since she was in her early teens.  She may have more palettes and brushes than she cares to admit:) After getting her culinary degree, working in Colorado''s progressive food industry, and seeing what a difference  clean, organic, all-natural nutrition can make, she was inspired to create BeauTeas.</p>\n<p>Teas are the perfect way to bring the power of plants into our lives. Our BeauTeas blends are loaded with anti-oxidants, anti-inflammatories, Alpha Hydroxy Acids, catechins, and many more valuable natural compounds.  When you drink our tea, your body absorbs the good nutrients more effectively than nutrients it gets from vitamins or topical application.  Drinking tea also helps you stay hydrated, which is super important for everything from how your skin and hair look, to your energy levels, to the health of your organs including your brain!  </p>\n<p>So join our BeauTeas Community, sip, relax, and enjoy feeling better and looking better. Build Your Beauty From Within!</p>\n<p> </p>\n<div style="text-align: center;"><img src="https://img.beauteas.com/pages/about-us-vanity-ritual.jpg" alt="" style="float: none;"></div>','\n',char(10)),NULL,'About Us','BeauTeas was created by blending a love of the beauty community with a love for nourishing the body (and soul) with all-natural organic plant-based goodness....',NULL,'published',1625798862,'story',NULL,0,1625798862,1785207965,NULL,NULL,2,0,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(5,'Brewing Directions','brewing-directions',replace('<p>Brewing your tea correctly will help ensure that it tastes delicious and that you are getting the most benefits from the organic herbs and flowers in our tea blends.  Don''t stress out over the precise temperatures, or freak out if you let it steep a little too long, these are just guidelines to help you get the most out of your tea.</p>\n<h2>Black Teas</h2>\n<ul class="specs"><li>205–212°F water</li><li>Steep 3–5 minutes</li></ul>\n<p>For Black teas, like our Clearly Calendula Morning, which is an Earl Grey based tea, we recommend using water that is between 205 and 212 degrees Fahrenheit.</p>\n<p>It''s best to boil water, and then let it cool for 30 seconds or so before pouring it into your tea cup.  But you can use boiling water if you''re in a rush:)</p>\n<p>Add the tea bag to the hot water in the cup, and let it steep for 3-5 minutes, before removing the tea bag.</p>\n<blockquote>If you let it steep too long the tea can taste too strong and slightly bitter (it''s still safe to drink).</blockquote>\n<figure class="blend"><a href="/product/clearly-calendula-morning">Clearly Calendula Morning</a></figure>\n<h2>Green Teas</h2>\n<ul class="specs"><li>175°F water</li><li>Steep 2–4 minutes</li></ul>\n<p>For Green teas, like our Clearly Calendula Afternoon, which is a Green tea, we recommend using water that is around 175 degrees Fahrenheit.</p>\n<p>It''s best to boil water, and then let it cool for 3 minutes or so before pouring it into your tea cup.  Or you can get a kettle which allows you to set the target temperature for 175 degrees.</p>\n<p>Add the tea bag to the hot water in the cup, and let it steep for 2-4 minutes, before removing the tea bag.</p>\n<blockquote>If you let it steep too long the tea can taste too strong and slightly bitter (it''s still safe to drink).</blockquote>\n<figure class="blend"><a href="/product/clearly-calendula-afternoon">Clearly Calendula Afternoon</a></figure>\n<h2>Herbal Teas</h2>\n<ul class="specs"><li>212°F water</li><li>Steep 5+ minutes</li></ul>\n<p>For Herbal teas, like our Clearly Calendula Evening, which is a herbal tea, we recommend using water that is around 212 degrees Fahrenheit.</p>\n<p>It''s best to boil water, and immediately pour it into your tea cup.</p>\n<p>Add the tea bag to the hot water in the cup, and let it steep for at least 5 minutes, you don''t have to remove the tea bag.</p>\n<blockquote>Generally letting herbal teas steep longer can make them taste a little stronger, but they won''t become bitter or unpleasant to drink.</blockquote>\n<figure class="blend"><a href="/product/clearly-calendula-evening">Clearly Calendula Evening</a></figure>\n<h2>Iced Teas</h2>\n<ul class="specs"><li>Cold brew 2+ hours</li><li>1 bag per 8–16 oz</li></ul>\n<p>Iced tea can be a super refreshing way to drink your tea, especially in warm weather, or at the gym.  Luckily it''s easy to make!  You can easily brew up a large amount of tea, using multiple tea bags in a pitcher.  Generally you will want one bag for every 8-16 oz of water, depending on how strong you like it.</p>\n<p><img src="https://img.beauteas.com/pages/brewing-iced-tea-pour.jpg" alt="Pouring freshly brewed iced tea into a travel bottle"></p>\n<p>Black teas must be hot brewed, using the directions above, and then chilled.  It''s usually best to let the hot tea cool to room temperature on your counter, and then move it into the refrigerator.</p>\n<p>For Green and Herbal teas, you can hot brew, and then chill like with Black teas. However you can also cold brew these teas as well, which might be easier.  Cold brewing is basically just adding your tea bags to cold water, and letting it steep for at least two hours and up to several days.</p>\n<p>You can do this inside a water bottle, mason jar, or large pitcher.  You can drink it with ice, or just chilled from the fridge.</p>\n<p>Play around with amounts and timing to figure out what you like best!</p>','\n',char(10)),NULL,'Brewing Directions','Brewing your tea correctly will help ensure that it tastes delicious and that you are getting the most benefits from the organic herbs and flowers in our tea...',NULL,'published',1624576251,'guide',NULL,0,1624576251,1785207965,NULL,NULL,2,0,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(7,'Clearly Calendula Sample Pack On Sale','clearly-calendula-sample-pack-on-sale','',NULL,'Clearly Calendula Sample Pack On Sale',NULL,NULL,'published',1638307799,'default',NULL,0,1638307799,1773009909,NULL,NULL,1,0,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(9,'FAQ','faq',replace('<p><strong>Are Your Teas Organic?</strong></p>\n<p>All of our teas are certified Organic by the USDA! We feel that organic ingredients are important for health and wellness and our planet.</p>\n<p> </p>\n<p><strong>Do Your Teas Have </strong><b>Caffeine?</b></p>\n<p>Some of our blends have natural caffeine from the tea leaves.  Black tea based blends, like our Clearly Calendula Morning blend have approximately 40-50 mg of caffeine, which is about half that of a cup of coffee.  Green tea based blends, like our Clearly Calendula Afternoon blend have approximately 20-30 mg of caffeine.  Our herbal blends, like our Clearly Calendula Evening blend are caffeine free and an excellent choice for drinking before bed, or if you are avoiding caffeine.  Caffeine from tea often is absorbed more slowly than from coffee or energy drinks, due to the tannins in the tea, so you tend to get less of a caffeine rush and crash, and more of a gradual energy that lasts longer.</p>\n<p> </p>\n<p><strong>Can I Drink Your Teas If I Am Pregnant?</strong></p>\n<p>Great question!  You should absolutely talk with your doctor about what is safe to eat and drink while pregnant.  In general pregnant people are advised to avoid consuming more than 200 mg of caffeine per day.  </p>\n<p>The amazing Calendula Flower, used in our skincare teas, is something you should avoid if pregnant.  While there are no clear studies on it, there are concerns about Calendula and it is considered "Likely Unsafe" for pregnant people by the NIH.  </p>\n<p> </p>\n<p><strong>Are Your Teas Just For Women?</strong></p>\n<p>Not at all!  Anyone can enjoy our teas and get the benefits, regardless of age or gender.  </p>\n<p> </p>\n<p> </p>','\n',char(10)),'Ingredients, caffeine, brewing and subscriptions: the things people ask us most.','FAQ','Are Your Teas Organic? All of our teas are certified Organic by the USDA! We feel that organic ingredients are important for health and wellness and our plan...',NULL,'published',1621192182,'faq',NULL,0,1621192182,1621192182,NULL,NULL,1,0,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(11,'Join Our Beautea Community','join-our-beautea-community',replace('<div style="display: none;"></div>\n<div style="display: none;"></div>\n<h2 style="text-align: center;">Please join our mailing list!</h2>\n<div style="text-align: center;"></div>\n<div style="text-align: center;">What you''ll get:</div>\n<div style="text-align: center;"></div>\n<h3 style="text-align: center;">Discounts!<br>Beauty Tips!<br>Fresh Product Drops!<br>More!</h3>\n<div style="text-align: center;"></div>\n<div style="text-align: center;"></div>\n<div style="text-align: center;">When you join you''ll get a discount code as a thank you. </div>\n<div style="text-align: center;"></div>\n<div style="text-align: center;">You can always unsubscribe if we ever bore you.</div>\n<p> </p>\n<div class="privy-embed-form" data-campaign="2539417"></div>','\n',char(10)),NULL,'Join Our Beautea Community','Please join our mailing list! What you''ll get: Discounts! Beauty Tips! Fresh Product Drops! More! When you join you''ll get a discount code as a thank you. Yo...',NULL,'published',1625329847,'default',NULL,0,1625329847,1625330067,NULL,NULL,1,0,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(12,'Maskne Treatment','maskne-treatment','',NULL,'Maskne Treatment',NULL,NULL,'published',1629135405,'default',NULL,0,1629135405,1773009912,NULL,NULL,1,0,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(13,'Subscriptions','subscriptions',replace('<div style="display: none;"></div>\n<div style="display: none;"></div>\n<p>The only thing better than drinking our tea, is drinking our tea every day!  In addition to tasting great, BeauTeas are functional teas.  This means that they are each carefully blended with ingredients designed to help your body in some way. </p>\n<div style="text-align: left;"></div>\n<p>Our organic herbs and flowers are much better for you than harsh chemicals, but they may take a little time to take effect.  We recommend drinking at least one cup of tea every day.  It''s even better if you can drink several cups of tea, as you''ll be getting more helpful plant based healing, and keeping hydrated.</p>\n<p>To help encourage you to drink tea every day, we offer Subscriptions for all of our teas.  Picking a Subscription means you''ll get your favorite tea delivered every month automatically.  To sweeten the (tea) pot, we offer <strong>a 10% Discount</strong> for Subscriptions.  </p>\n<p>Save more money, drink more tea, be more healthy!</p>\n<p>You can always change or cancel your subscription at anytime.  We don''t believe in lock-in.  </p>\n<p><img src="https://img.beauteas.com/pages/subscriptions-vanity-flatlay.jpg" width="1024x1024" height="1024x1024"></p>','\n',char(10)),NULL,'Subscriptions','The only thing better than drinking our tea, is drinking our tea every day! In addition to tasting great, BeauTeas are functional teas. This means that they ...',NULL,'published',1625358265,'story',NULL,0,1625358265,1785207965,NULL,NULL,2,0,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(14,'Refund & Return Policy','refund-policy','<p><strong>Last Updated:</strong> 2026-07-10</p><h2>Our Promise</h2><p>We want you to love your BeauTeas ritual. If you are not completely satisfied with your purchase, we are here to help.</p><h2>Return Window</h2><p>You may request a return within <strong>30 days</strong> of your delivery date. Because our teas are consumable products, items must be unopened and in their original, resalable packaging to be eligible, for health and safety reasons. Opened or partially used items cannot be returned unless they arrived damaged, defective, or incorrect.</p><h2>How to Start a Return</h2><p>Email our team at <a href="mailto:hello@beauteas.com">hello@beauteas.com</a> with your order number and the item(s) you would like to return, and we will send you return instructions. Please do not ship items back before contacting us.</p><h2>Refunds</h2><ul><li><strong>No restocking fee.</strong> We never charge a restocking fee on returned items.</li><li>Once we receive and inspect your return, your refund is issued to your original payment method.</li><li>Refunds are typically processed within 5 to 10 business days after we receive your return, though your bank or card issuer may take additional time to post the credit.</li><li>The minimum refund we process is <strong>$5.00</strong>. Amounts below this may be issued as store credit instead.</li><li>Original shipping charges are non-refundable except where an item arrived damaged, defective, or incorrect.</li></ul><h2>Damaged, Defective, or Incorrect Items</h2><p>If your order arrives damaged or you receive the wrong item, please contact us within 30 days of delivery and we will make it right with a replacement or a full refund, including any shipping costs, at no charge to you.</p><h2>Subscriptions</h2><p>You can change, pause, or cancel a tea subscription at any time from your account before your next renewal. Subscription orders that have already shipped follow the same 30-day return policy described above.</p><h2>Questions</h2><p>Reach us any time at <a href="mailto:hello@beauteas.com">hello@beauteas.com</a> and a member of our team will be happy to help.</p>','What to do if something isn''t right.',NULL,'How to return an item and request a refund from BeauTeas: 30-day return window, no restocking fee, and refunds to your original payment method.',NULL,'published',NULL,'legal',NULL,110,1783726014,1783726014,NULL,NULL,1,0,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(15,'Shipping Policy','shipping-policy','<p><strong>Last Updated:</strong> 2026-07-10</p><h2>Order Processing</h2><p>Orders are processed and packed within 1 to 2 business days (Monday through Friday, excluding holidays). You will receive a confirmation email with tracking as soon as your order ships.</p><h2>Shipping Methods and Delivery Times</h2><p>We currently ship within the United States. At checkout you can choose from:</p><ul><li><strong>Standard</strong>: estimated 5 to 7 business days.</li><li><strong>Express</strong>: estimated 2 to 3 business days.</li><li><strong>Overnight</strong>: next business day where available.</li></ul><p>Delivery estimates begin once your order leaves our facility and do not include processing time. Carrier delays, weather, and peak periods can occasionally affect delivery windows.</p><h2>Shipping Rates</h2><p>Shipping is calculated at checkout based on the method you select and your destination. Any active free-shipping promotion is applied automatically to qualifying orders.</p><h2>Tracking Your Order</h2><p>Once your order ships, you can track your package using the link in your shipping confirmation email or from your order history in your account.</p><h2>Lost or Delayed Packages</h2><p>If your tracking has not updated or your package has not arrived within the estimated window, contact us at <a href="mailto:hello@beauteas.com">hello@beauteas.com</a> and we will help track it down.</p><h2>International Orders</h2><p>We are not shipping internationally at this time. If you are outside the United States and would like to order, please reach out and we will let you know when international shipping becomes available.</p>','How and when your order gets to you.',NULL,'BeauTeas shipping information: order processing times, domestic shipping methods and estimated delivery windows, tracking, and lost-package help.',NULL,'published',NULL,'legal',NULL,111,1783726014,1783726014,NULL,NULL,1,0,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(16,'Contact Us','contact','<p>We would love to hear from you. Whether you have a question about our organic skincare teas, your order, a subscription, or you just want to say hello, our team is here to help.</p><h2>Email Us</h2><p>The fastest way to reach us is by email at <a href="mailto:hello@beauteas.com">hello@beauteas.com</a>. We aim to respond to every message within 1 to 2 business days.</p><h2>Customer Support Hours</h2><p>Our support team is available Monday through Friday, 9:00 AM to 5:00 PM Mountain Time, excluding public holidays.</p><h2>Order and Shipping Questions</h2><p>For help with an existing order, please include your order number so we can assist you as quickly as possible. You can also review our <a href="/shipping-policy">Shipping Policy</a> and <a href="/refund-policy">Refund &amp; Return Policy</a> for quick answers to common questions.</p><h2>Frequently Asked Questions</h2><p>Many questions are answered on our <a href="/faq">FAQ page</a>, a great first stop for details about our ingredients, brewing, and subscriptions.</p><h2>Stay Connected</h2><p>Follow along for beauty tips, new blends, and special offers on Instagram, Facebook, and Pinterest.</p>',NULL,NULL,'Get in touch with the BeauTeas team. Email us at hello@beauteas.com for questions about our organic skincare teas, orders, shipping, or subscriptions.',NULL,'published',NULL,'contact',NULL,112,1783726014,1783726014,NULL,NULL,1,0,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(17,'Privacy Policy','privacy-policy','<p><strong>Last Updated:</strong> 2026-07-14</p><p>This Privacy Policy explains how BeauTeas ("we," "us," or "our") collects, uses, and shares personal information when you visit beauteas.com, create an account, place an order, subscribe, or chat with our AI assistant. We are committed to handling your information responsibly and giving you meaningful control over it.</p><h2>1. Information We Collect</h2><p>We collect the following categories of personal information:</p><ul><li><strong>Account information</strong>: your name, email address, and login credentials, managed on our behalf by our authentication provider.</li><li><strong>Order and transaction information</strong>: the products you buy, your order history, and your shipping and billing addresses.</li><li><strong>Payment information</strong>: your card details are collected and processed directly by our payment processor. We do not store full card numbers on our systems; we retain only limited details such as the card brand, the last four digits, and a payment reference.</li><li><strong>Subscription information</strong>: the plans you enroll in and their status and renewal schedule.</li><li><strong>AI assistant interactions</strong>: the messages you send to Chai, our shopping assistant, which are processed to generate responses and recommendations.</li><li><strong>Approximate location</strong>: a coarse, city-level location derived from your network connection, used to tailor content such as shipping estimates.</li><li><strong>Technical and usage data</strong>: information such as your browser type, device, and how you interact with the site, collected to operate and secure the service.</li></ul><h2>2. How We Use Your Information</h2><p>We use personal information to:</p><ul><li>Process and fulfill your orders and manage your subscriptions;</li><li>Create and maintain your account and authenticate you;</li><li>Provide the AI assistant and personalize product recommendations;</li><li>Send transactional messages such as order confirmations, shipping updates, and review reminders;</li><li>Provide customer support and respond to your inquiries;</li><li>Detect, prevent, and address fraud, abuse, and security issues; and</li><li>Comply with our legal, tax, and accounting obligations.</li></ul><h2>3. Service Providers We Share Information With</h2><p>We do not sell your personal information. We share it only with the service providers (processors) that help us operate the store, and only as needed to provide the service:</p><table><thead><tr><th>Provider</th><th>Purpose</th><th>Information involved</th></tr></thead><tbody><tr><td>Stripe</td><td>Payment processing and subscription billing</td><td>Payment and billing details</td></tr><tr><td>Clerk</td><td>Account authentication and identity management</td><td>Name, email, login credentials</td></tr><tr><td>Resend</td><td>Sending transactional email</td><td>Name, email, order details</td></tr><tr><td>Cloudflare</td><td>Website hosting, database, media storage, and content delivery</td><td>Data processed by the site</td></tr><tr><td>Cloudflare Workers AI</td><td>Powering the Chai AI assistant and search</td><td>Your chat messages and related product context</td></tr></tbody></table><p>We may also disclose information when required by law, to enforce our terms, or in connection with a business transfer such as a merger or acquisition.</p><h2>4. Cookies and Tracking</h2><p>We use cookies and similar technologies that are strictly necessary to operate the site, for example to keep you signed in and to maintain your shopping cart. We do not currently use third-party advertising or marketing tracking pixels. If that changes, we will update this policy and, where required, provide a cookie consent choice.</p><h2>5. Data Retention</h2><p>We keep personal information only as long as necessary for the purposes described in this policy. Order and transaction records are retained for the period required by tax, accounting, and legal obligations (generally several years). Account information is retained while your account is active and is deleted or anonymized after you close your account or request deletion, unless we are required to keep it.</p><h2>6. Your Privacy Rights</h2><p>Depending on where you live, you may have some or all of the following rights regarding your personal information:</p><ul><li><strong>Access / know</strong>: request a copy of the personal information we hold about you and how we use it;</li><li><strong>Correction</strong>: ask us to correct inaccurate information;</li><li><strong>Deletion</strong>: ask us to delete your personal information;</li><li><strong>Portability</strong>: receive your information in a portable format;</li><li><strong>Objection / restriction</strong>: object to or restrict certain processing; and</li><li><strong>Withdraw consent</strong>: withdraw consent where we rely on it, without affecting processing already carried out.</li></ul><p><strong>California residents (CCPA/CPRA):</strong> You have the right to know, delete, and correct your personal information, and the right to opt out of the sale or sharing of personal information. <strong>We do not sell or share your personal information for cross-context behavioral advertising or for monetary or other valuable consideration</strong>, so there is no such opt-out for you to exercise. We will not discriminate against you for exercising your rights.</p><p><strong>EU / UK residents (GDPR / UK GDPR):</strong> In addition to the rights above, you may lodge a complaint with your local data protection authority. We process your information on the legal bases of performing our contract with you, our legitimate interests in operating and securing the store, your consent where applicable, and compliance with legal obligations.</p><p>To exercise any of these rights, contact us using the details below. We will verify your request and respond within the time required by applicable law.</p><h2>7. Data Security</h2><p>We use administrative and technical safeguards, and rely on reputable providers, to protect personal information. No method of transmission or storage is completely secure, however, and we cannot guarantee absolute security.</p><h2>8. Children''s Privacy</h2><p>Our store is not directed to children under 16, and we do not knowingly collect personal information from them. If you believe a child has provided us information, please contact us and we will delete it.</p><h2>9. Changes to This Policy</h2><p>We may update this Privacy Policy from time to time. When we do, we will revise the "Last Updated" date above and, where appropriate, provide additional notice.</p><h2>10. Contact Us</h2><p>If you have questions about this Privacy Policy or wish to exercise your privacy rights, contact us at:</p><p>BeauTeas<br>5504 S. Lilly Creek Ct.<br>Byers, CO 80103<br>Email: <a href="mailto:hello@beauteas.com">hello@beauteas.com</a></p>',NULL,NULL,'Learn how we collect, use, and protect your personal information, the processors we use, and your privacy rights.',NULL,'published',NULL,'legal',NULL,100,1784004155,1784004155,NULL,NULL,1,1,NULL,NULL,NULL,0,NULL);
INSERT OR REPLACE INTO "pages" ("id","title","slug","content","excerpt","meta_title","meta_description","meta_keywords","status","published_at","template","parent_id","sort_order","created_at","updated_at","created_by","updated_by","version","show_in_nav","nav_title","custom_css","custom_js","is_protected","required_roles") VALUES(18,'Terms of Service','terms-of-service','<p><strong>Last Updated:</strong> 2026-07-14</p><p>These Terms of Service ("Terms") govern your access to and use of beauteas.com and any purchases you make from BeauTeas ("we," "us," or "our"). By using the site or placing an order, you agree to these Terms. If you do not agree, please do not use the site.</p><h2>1. Eligibility and Accounts</h2><p>You must be at least 18 years old, or the age of majority where you live, to purchase from us. If you create an account, you are responsible for keeping your login credentials confidential and for all activity that occurs under your account. Please notify us promptly of any unauthorized use.</p><h2>2. Products and Orders</h2><p>Our products are organic teas formulated to support skin health. We describe our products as accurately as possible, but we do not warrant that product descriptions, ingredients, or other content are complete or error-free. All orders are subject to acceptance and availability, and we may refuse or cancel an order at our discretion, including where we suspect fraud or an error in pricing or product information.</p><h2>3. Pricing and Payment</h2><p>Prices are shown in U.S. dollars and may change at any time. Applicable taxes and shipping are calculated at checkout. Payment is processed by our third-party payment processor, and by placing an order you authorize us to charge your selected payment method for the total amount of your order.</p><h2>4. Subscriptions and Recurring Billing</h2><p>If you enroll in a subscription, you authorize us to charge your payment method on a recurring basis according to the plan you selected until you cancel. You may pause, change, or cancel your subscription at any time from your account before the next renewal date. Cancellation stops future renewals; it does not retroactively refund an order that has already been processed.</p><h2>5. Shipping, Returns, and Refunds</h2><p>Shipping timeframes, returns, and refunds are governed by our <a href="/shipping-policy">Shipping Policy</a> and our <a href="/refund-policy">Refund &amp; Return Policy</a>, which are incorporated into these Terms by reference.</p><h2>6. Health Disclaimer</h2><p>Our products are not intended to diagnose, treat, cure, or prevent any disease, and our content is not medical advice. Consult a qualified healthcare professional before using our products if you are pregnant, nursing, taking medication, or have a medical condition or known allergies. Discontinue use and seek advice if you experience an adverse reaction.</p><h2>7. AI Assistant</h2><p>Our AI shopping assistant, Chai, provides automated product information and suggestions and may occasionally be inaccurate or incomplete. Its responses are offered for convenience only and are not professional, medical, or legal advice. Please verify important details before relying on them.</p><h2>8. Acceptable Use</h2><p>You agree not to misuse the site, including by attempting to gain unauthorized access, interfering with its operation, scraping or harvesting data, or using it for any unlawful purpose.</p><h2>9. Intellectual Property</h2><p>The site and its content, including text, graphics, logos, and images, are owned by us or our licensors and are protected by intellectual property laws. You may not copy, reproduce, or distribute our content without our permission.</p><h2>10. Disclaimers and Limitation of Liability</h2><p>The site and products are provided on an "as is" and "as available" basis, without warranties of any kind, whether express or implied, to the fullest extent permitted by law. To the maximum extent permitted by law, we will not be liable for any indirect, incidental, or consequential damages arising from your use of the site or products, and our total liability for any claim will not exceed the amount you paid for the order giving rise to the claim.</p><h2>11. Governing Law</h2><p>These Terms are governed by the laws of the State of Colorado, without regard to its conflict-of-laws rules. Any dispute will be subject to the exclusive jurisdiction of the state and federal courts located in Colorado.</p><h2>12. Changes to These Terms</h2><p>We may update these Terms from time to time. Changes take effect when we post the revised Terms and update the "Last Updated" date above. Your continued use of the site after changes take effect constitutes acceptance of the revised Terms.</p><h2>13. Contact Us</h2><p>Questions about these Terms? Contact us at:</p><p>BeauTeas<br>5504 S. Lilly Creek Ct.<br>Byers, CO 80103<br>Email: <a href="mailto:hello@beauteas.com">hello@beauteas.com</a></p>',NULL,NULL,'Read the terms and conditions for using BeauTeas, including orders, subscriptions, health disclaimer, and governing law.',NULL,'published',NULL,'legal',NULL,101,1784004155,1784004155,NULL,NULL,1,1,NULL,NULL,NULL,0,NULL);
